/* ScshOperPlcyMapper.upsertList */ MERGE INTO PMOWN.TN_PM_SCSH_OPER_PLCY A USING (
SELECT #{item.operYmd} AS OPER_YMD, #{item.operHour} AS OPER_HOUR, #{item.tmnlId} AS TMNL_ID, #{item.dptgtNo} AS DPTGT_NO, #{item.scshOperCntom} AS SCSH_OPER_CNTOM FROM DUAL
) B ON ( A.OPER_YMD = B.OPER_YMD AND A.OPER_HOUR = B.OPER_HOUR AND A.TMNL_ID = B.TMNL_ID AND A.DPTGT_NO = B.DPTGT_NO ) WHEN MATCHED THEN UPDATE SET A.SCSH_OPER_CNTOM = B.SCSH_OPER_CNTOM, A.LAST_MDFR_ID = #{regId}, A.LAST_MDFR_IP_ADDR = #{regIp}, A.LAST_MDFCN_DT = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT ( OPER_YMD, OPER_HOUR, TMNL_ID, DPTGT_NO, SCSH_OPER_CNTOM, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) VALUES ( B.OPER_YMD, B.OPER_HOUR, B.TMNL_ID, B.DPTGT_NO, B.SCSH_OPER_CNTOM, #{regId}, #{regIp}, SYSTIMESTAMP )
